<?php
require_once __DIR__ . '/../../config/config.php';
if (!isLoggedIn() || ($_SESSION['role'] ?? '') !== 'teacher') { header('Location: ../login.php'); exit(); }
$teacherUser=(int)($_SESSION['user_id']??0); $studentId=(int)(filter_input(INPUT_GET,'student_id',FILTER_VALIDATE_INT)?:0); $offeringId=(int)(filter_input(INPUT_GET,'offering_id',FILTER_VALIDATE_INT)?:0);
$stmt=$pdo->prepare("SELECT t.teacher_id FROM teachers t WHERE t.user_id=? LIMIT 1");$stmt->execute([$teacherUser]);$teacher=$stmt->fetch(PDO::FETCH_ASSOC);if(!$teacher||!$studentId||!$offeringId)die('Invalid request.');
$stmt=$pdo->prepare("SELECT co.offering_id,co.quarter,sub.subject_name,sec.section_name,sy.label school_year,s.student_id,s.student_lrn,s.firstname,s.lastname,s.middlename FROM classofferings co JOIN subjects sub ON sub.subject_id=co.subject_id JOIN sections sec ON sec.section_id=co.section_id JOIN schoolyears sy ON sy.school_year_id=co.school_year_id JOIN enrollments e ON e.offering_id=co.offering_id AND e.student_id=? AND e.status='active' JOIN students s ON s.student_id=e.student_id WHERE co.offering_id=? AND co.teacher_id=? AND co.status='active' LIMIT 1");$stmt->execute([$studentId,$offeringId,$teacher['teacher_id']]);$student=$stmt->fetch(PDO::FETCH_ASSOC);if(!$student)die('Student or class not found.');
$stmt=$pdo->prepare("SELECT a.assignment_id,a.title,a.points,sub.score,sub.status,sub.attempt_number FROM assignments a LEFT JOIN submissions sub ON sub.assignment_id=a.assignment_id AND sub.student_id=? AND sub.attempt_number=(SELECT MAX(x.attempt_number) FROM submissions x WHERE x.assignment_id=a.assignment_id AND x.student_id=?) WHERE a.offering_id=? ORDER BY a.created_at,a.assignment_id");$stmt->execute([$studentId,$studentId,$offeringId]);$assignments=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare("SELECT q.quiz_id,q.title,qa.score,qa.max_score,qa.status,qa.attempt_number FROM quizzes q LEFT JOIN quiz_attempts qa ON qa.quiz_id=q.quiz_id AND qa.student_id=? AND qa.attempt_number=(SELECT MAX(x.attempt_number) FROM quiz_attempts x WHERE x.quiz_id=q.quiz_id AND x.student_id=?) WHERE q.offering_id=? ORDER BY q.created_at,q.quiz_id");$stmt->execute([$studentId,$studentId,$offeringId]);$quizzes=$stmt->fetchAll(PDO::FETCH_ASSOC);
$aPerc=[];$qPerc=[];foreach($assignments as &$a){$a['percentage']=($a['score']!==null&&(float)$a['points']>0)?((float)$a['score']/(float)$a['points'])*100:null;if($a['percentage']!==null)$aPerc[]=$a['percentage'];}unset($a);foreach($quizzes as &$q){$q['percentage']=($q['score']!==null&&(float)$q['max_score']>0)?((float)$q['score']/(float)$q['max_score'])*100:null;if($q['percentage']!==null)$qPerc[]=$q['percentage'];}unset($q);
function meanScore($v){return $v?round(array_sum($v)/count($v),1):null;}function scoreClass($v){if($v===null)return'none';return $v>=90?'excellent':($v>=80?'good':($v>=75?'fair':'low'));}$quizAvg=meanScore($qPerc);$assignmentAvg=meanScore($aPerc);$overall=meanScore(array_filter([$quizAvg,$assignmentAvg],fn($x)=>$x!==null));$name=htmlspecialchars($student['firstname'].' '.$student['lastname']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $name ?> · Grade Details</title><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/grade_book.css"><style>.details-page{max-width:1300px;margin:auto}.back-link{display:inline-flex;align-items:center;gap:7px;color:#4f46e5;text-decoration:none;font-weight:700;font-size:13px;margin-bottom:18px}.student-hero{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:20px;display:flex;align-items:center;justify-content:space-between;gap:18px}.student-profile{display:flex;align-items:center;gap:14px}.big-avatar{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:#eef2ff;color:#4f46e5;font-weight:900}.student-profile h2{margin:0;font-size:22px}.student-profile p{margin:5px 0 0;color:#64748b;font-size:13px}.score-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.score-card{background:#fff;border:1px solid #e5eaf0;border-radius:15px;padding:18px}.score-card span,.score-card small{display:block;color:#64748b;font-size:12px}.score-card strong{font-size:26px;display:block;margin:6px 0}.detail-panel{background:#fff;border:1px solid #e5eaf0;border-radius:15px;margin-top:16px;overflow:hidden}.detail-panel h3{margin:0;padding:18px 20px;border-bottom:1px solid #edf0f4;font-size:16px}.score-list{width:100%;border-collapse:collapse}.score-list th,.score-list td{text-align:left;padding:13px 18px;border-bottom:1px solid #eef1f4;font-size:13px}.score-list th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.score-list td:last-child,.score-list th:last-child{text-align:right}.score-value{font-weight:800}.score-value.excellent{color:#047857}.score-value.good{color:#2563eb}.score-value.fair{color:#b45309}.score-value.low{color:#dc2626}.score-value.none{color:#94a3b8}.status{font-size:11px;color:#64748b}.mobile-table{overflow:auto}.empty-row{text-align:center;color:#94a3b8;padding:28px!important}@media(max-width:700px){.student-hero{align-items:flex-start}.score-cards{grid-template-columns:1fr}.student-profile h2{font-size:18px}.score-list{min-width:570px}.student-hero{display:block}.student-hero .eyebrow{margin-top:14px}}</style></head><body><?php include '../../includes/teachers_sidebar.php'; ?><main class="main-content"><div class="page-wrap details-page"><a class="back-link" href="grade_book.php?offering_id=<?=$offeringId?>"><i class="fas fa-arrow-left"></i> Back to Grade Book</a><section class="student-hero"><div class="student-profile"><div class="big-avatar"><?=strtoupper(substr($student['firstname'],0,1).substr($student['lastname'],0,1))?></div><div><h2><?=$name?></h2><p>LRN: <?=htmlspecialchars($student['student_lrn'])?></p></div></div><div><p class="eyebrow">CLASS</p><strong><?=htmlspecialchars($student['subject_name'].' · '.$student['section_name'])?></strong><p class="page-subtitle"><?=htmlspecialchars($student['quarter'].' · '.$student['school_year'])?></p></div></section><section class="score-cards"><article class="score-card"><span>Overall Average</span><strong class="score-value <?=scoreClass($overall)?>"><?=$overall!==null?$overall.'%':'—'?></strong><small>Quiz + assignment average</small></article><article class="score-card"><span>Quiz Average</span><strong class="score-value <?=scoreClass($quizAvg)?>"><?=$quizAvg!==null?$quizAvg.'%':'—'?></strong><small><?=count($quizzes)?> quizzes</small></article><article class="score-card"><span>Assignment Average</span><strong class="score-value <?=scoreClass($assignmentAvg)?>"><?=$assignmentAvg!==null?$assignmentAvg.'%':'—'?></strong><small><?=count($assignments)?> assignments</small></article></section><section class="detail-panel"><h3><i class="fas fa-file-circle-question"></i> Quiz Scores</h3><div class="mobile-table"><table class="score-list"><thead><tr><th>Quiz</th><th>Score</th><th>Percentage</th><th>Status</th></tr></thead><tbody><?php foreach($quizzes as $q):?><tr><td><strong><?=htmlspecialchars($q['title'])?></strong></td><td><?=$q['score']!==null?htmlspecialchars($q['score']).' / '.htmlspecialchars($q['max_score']):'—'?></td><td class="score-value <?=scoreClass($q['percentage'])?>"><?=$q['percentage']!==null?number_format($q['percentage'],1).'%':'N/A'?></td><td class="status"><?=$q['score']!==null?'Graded':'Not taken'?></td></tr><?php endforeach;?><?php if(!$quizzes):?><tr><td colspan="4" class="empty-row">No quizzes found for this class.</td></tr><?php endif;?></tbody></table></div></section><section class="detail-panel"><h3><i class="fas fa-clipboard-check"></i> Assignment Scores</h3><div class="mobile-table"><table class="score-list"><thead><tr><th>Assignment</th><th>Score</th><th>Percentage</th><th>Status</th></tr></thead><tbody><?php foreach($assignments as $a):?><tr><td><strong><?=htmlspecialchars($a['title'])?></strong></td><td><?=$a['score']!==null?htmlspecialchars($a['score']).' / '.htmlspecialchars($a['points']):'—'?></td><td class="score-value <?=scoreClass($a['percentage'])?>"><?=$a['percentage']!==null?number_format($a['percentage'],1).'%':'N/A'?></td><td class="status"><?=$a['score']!==null?'Graded':'Not submitted'?></td></tr><?php endforeach;?><?php if(!$assignments):?><tr><td colspan="4" class="empty-row">No assignments found for this class.</td></tr><?php endif;?></tbody></table></div></section></div></main></body></html>